/**
 * Compares the JSON schemas generated by gulp.schema.js with a previous set - a published release, or a directory -
 * using jsoncompat, which decides whether one schema accepts everything the other does.
 *
 * A schema set is `{files, resources}`: `files` maps each schema's path (relative to `dist/schema/`) to its text;
 * `resources` maps the `$id` of every schema those files reference, directly or not, to its parsed contents.
 */
const fs = require('fs');
const path = require('path');
const {generateSchemas} = require('./gulp.schema.js');

const NPM_PACKAGE = 'prebid.js';
const CDN = `https://cdn.jsdelivr.net/npm/${NPM_PACKAGE}`;
const CDN_API = `https://data.jsdelivr.com/v1/packages/npm/${NPM_PACKAGE}`;
// the sets being compared can share `$id`s (e.g. two builds of the same version), so freshly generated schemas get their own
const GENERATED_BASE_URL = 'https://generated.invalid/schema/';

let jsoncompat;
async function loadJsoncompat() {
  if (jsoncompat == null) {
    const mod = await import('jsoncompat');
    mod.initSync({module: fs.readFileSync(require.resolve('jsoncompat/jsoncompat_wasm_bg.wasm'))});
    jsoncompat = mod;
  }
  return jsoncompat;
}

function refs(schema, base) {
  const found = new Set();
  const visit = (node) => {
    if (Array.isArray(node)) return node.forEach(visit);
    if (node == null || typeof node !== 'object') return;
    if (typeof node.$ref === 'string' && !node.$ref.startsWith('#')) {
      const url = new URL(node.$ref, base);
      url.hash = '';
      found.add(url.toString());
    }
    Object.values(node).forEach(visit);
  };
  visit(schema);
  return found;
}

/**
 * Add to `resources` everything `schemas` reference, fetching what is missing with `load(url)`.
 */
async function resolveRefs(schemas, resources, load) {
  const queue = [...schemas];
  while (queue.length > 0) {
    const schema = queue.shift();
    for (const url of refs(schema, schema.$id)) {
      if (!Object.hasOwn(resources, url)) {
        const loaded = await load(url);
        if (loaded == null) throw new Error(`Schema '${schema.$id}' references '${url}', which could not be found`);
        resources[url] = loaded;
        queue.push(loaded);
      }
    }
  }
}

async function makeSet(files, load = () => null) {
  const resources = {};
  const schemas = Object.values(files).map(text => JSON.parse(text));
  schemas.forEach(schema => { resources[schema.$id] = schema; });
  await resolveRefs(schemas, resources, load);
  return {files, resources};
}

function generatedSet(options) {
  const schemas = generateSchemas({baseUrl: GENERATED_BASE_URL, ...options});
  return makeSet(Object.fromEntries(Object.entries(schemas).map(([file, schema]) => [file, JSON.stringify(schema, null, 2) + '\n'])));
}

function dirSet(dir) {
  const files = fs.existsSync(dir) ? fs.readdirSync(dir, {recursive: true}).filter(file => file.endsWith('.json')) : [];
  return makeSet(Object.fromEntries(files.map(file => [file.split(path.sep).join('/'), fs.readFileSync(path.join(dir, file), 'utf8')])));
}

async function fetchOk(url, as) {
  const response = await fetch(url);
  if (response.status === 404) return null;
  if (!response.ok) throw new Error(`GET ${url}: ${response.status} ${response.statusText}`);
  return response[as]();
}

/**
 * @param {string} specifier npm version or range (as jsDelivr resolves it) of the release to load
 */
async function publishedSet(specifier) {
  const {version} = await fetchOk(`${CDN_API}/resolved?specifier=${encodeURIComponent(specifier)}`, 'json') ?? {};
  if (version == null) throw new Error(`No published version of ${NPM_PACKAGE} matches '${specifier}'`);
  const listing = await fetchOk(`${CDN_API}@${version}?structure=flat`, 'json');
  const prefix = '/dist/schema/';
  const paths = (listing?.files ?? []).map(({name}) => name).filter(name => name.startsWith(prefix) && name.endsWith('.json'));
  const files = Object.fromEntries(await Promise.all(paths.map(async name => [name.slice(prefix.length), await fetchOk(`${CDN}@${version}${name}`, 'text')])));
  return {version, ...await makeSet(files, async url => {
    const text = await fetchOk(url, 'text');
    return text == null ? null : JSON.parse(text);
  })};
}

function previousRelease(version) {
  // the latest release preceding this version, on any line: `<11.50.0` for 11.50.0 or 11.50.0-pre, `<10.5.1` for 10.5.1
  return `<${version.replace(/-.*$/, '')}`;
}

function againstSet(against, currentVersion) {
  if (against != null && fs.existsSync(against) && fs.statSync(against).isDirectory()) {
    return dirSet(against).then(set => ({...set, label: `\`${against}\``, isRelease: false}));
  }
  return publishedSet(against ?? previousRelease(currentVersion)).then(set => ({...set, label: `\`${NPM_PACKAGE}@${set.version}\``, isRelease: true}));
}

function closure(root, resources) {
  const found = {};
  const queue = [root];
  while (queue.length > 0) {
    const schema = queue.shift();
    for (const url of refs(schema, schema.$id)) {
      if (url !== root.$id && !Object.hasOwn(found, url)) {
        found[url] = resources[url];
        queue.push(resources[url]);
      }
    }
  }
  return found;
}

function withoutId({$id, ...schema}) {
  return schema;
}

function pointer(parent, key) {
  return `${parent}/${String(key).replace(/~/g, '~0').replace(/\//g, '~1')}`;
}

function isObject(value) {
  return value != null && typeof value === 'object' && !Array.isArray(value);
}

/**
 * Structural differences between two JSON values, as `{op: 'add' | 'remove' | 'change', path, from, to}`.
 * Arrays of the same length are compared element by element; otherwise as sets, so that inserting into
 * `anyOf` or `required` shows only what was inserted.
 */
function jsonDiff(from, to, at = '') {
  if (isObject(from) && isObject(to)) {
    const keys = [...Object.keys(from), ...Object.keys(to).filter(key => !Object.hasOwn(from, key))];
    return keys.flatMap(key => {
      if (!Object.hasOwn(to, key)) return [{op: 'remove', path: pointer(at, key), from: from[key]}];
      if (!Object.hasOwn(from, key)) return [{op: 'add', path: pointer(at, key), to: to[key]}];
      return jsonDiff(from[key], to[key], pointer(at, key));
    });
  }
  if (Array.isArray(from) && Array.isArray(to)) {
    if (from.length === to.length) return from.flatMap((item, i) => jsonDiff(item, to[i], pointer(at, i)));
    const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
    return [
      ...from.map((item, i) => [item, i]).filter(([item]) => !to.some(other => same(item, other)))
        .map(([item, i]) => ({op: 'remove', path: pointer(at, i), from: item})),
      ...to.map((item, i) => [item, i]).filter(([item]) => !from.some(other => same(item, other)))
        .map(([item, i]) => ({op: 'add', path: pointer(at, i), to: item})),
    ];
  }
  return JSON.stringify(from) === JSON.stringify(to) ? [] : [{op: 'change', path: at, from, to}];
}

/**
 * Compare every schema in `current` with the one at the same path in `previous`.
 *
 * Each result has the schema's `file` and a `status`:
 *  - `compatible`: each schema accepts everything the other does;
 *  - `incompatible`, with `counterexamples` keyed by direction - `rejectedByPrevious` (a payload the current schema
 *    allows, but the previous one rejects) and/or `rejectedByCurrent` (the reverse);
 *  - `unknown`, with a `reason`, when jsoncompat cannot decide;
 *  - `added` or `removed`.
 * Results that are not `compatible` also have the structural `diff` between the two files (`$id` aside), if both exist.
 */
async function compareSets(previous, current) {
  const {analyze_compat: analyzeCompat} = await loadJsoncompat();
  const files = [...new Set([...Object.keys(current.files), ...Object.keys(previous.files)])].sort();
  return files.map(file => {
    if (!Object.hasOwn(previous.files, file)) return {file, status: 'added'};
    if (!Object.hasOwn(current.files, file)) return {file, status: 'removed'};
    const before = JSON.parse(previous.files[file]);
    const after = JSON.parse(current.files[file]);
    // jsoncompat refuses resources that redefine the schemas being compared
    const options = JSON.stringify({resources: {...closure(before, previous.resources), ...closure(after, current.resources)}});
    const counterexamples = {};
    const reasons = [];
    [['serializer', 'rejectedByPrevious'], ['deserializer', 'rejectedByCurrent']].forEach(([role, direction]) => {
      const result = analyzeCompat(previous.files[file], current.files[file], role, options);
      if (result.status === 'incompatible') counterexamples[direction] = result.counterexample_json;
      if (result.status === 'unknown') reasons.push(result.reason);
    });
    if (Object.keys(counterexamples).length === 0 && reasons.length === 0) return {file, status: 'compatible'};
    const diff = jsonDiff(withoutId(before), withoutId(after));
    return Object.keys(counterexamples).length > 0
      ? {file, status: 'incompatible', counterexamples, diff}
      : {file, status: 'unknown', reason: reasons.join('; '), diff};
  });
}

function truncate(text, max = 300) {
  return text.length > max ? `${text.slice(0, max)}…` : text;
}

function formatDiff(diff) {
  return diff.map(({op, path, from, to}) => {
    const value = (v) => truncate(JSON.stringify(v));
    if (op === 'add') return `+ ${path}: ${value(to)}`;
    if (op === 'remove') return `- ${path}: ${value(from)}`;
    return `! ${path}: ${value(from)} → ${value(to)}`;
  }).join('\n');
}

const FENCE = '```';

/**
 * Markdown report of the results that are not `compatible`; null if there are none.
 */
function formatReport(results, against) {
  const changed = results.filter(({status}) => status !== 'compatible');
  if (changed.length === 0) return null;
  const lines = [`### JSON schema changes`, '', `${changed.length} of ${results.length} schema(s) under \`dist/schema/\` changed${against ? ` since ${against}` : ''}.`];
  changed.forEach(({file, status, counterexamples, reason, diff}) => {
    lines.push('', `#### \`${file}\`: ${status}`);
    if (diff?.length > 0) lines.push('', `${FENCE}diff`, formatDiff(diff), FENCE);
    if (reason) lines.push('', `Could not determine compatibility: ${reason}`);
    [
      ['rejectedByPrevious', 'Payloads the previous schema rejects'],
      ['rejectedByCurrent', 'Payloads the previous schema allowed, but are no longer valid'],
    ].filter(([direction]) => counterexamples?.[direction]).forEach(([direction, summary]) => {
      lines.push('', `<details><summary>${summary}, e.g.</summary>`, '', `${FENCE}json`, truncate(counterexamples[direction], 2000), FENCE, '', '</details>');
    });
  });
  return lines.join('\n');
}

/**
 * Task that exits successfully only if the schemas generated from the sources are compatible with a previous set.
 *
 * `--against` is a directory, or an npm version or range; it defaults to the release preceding the current version.
 * `--report <file>` also writes the report, in Markdown, to that file (an empty file if nothing changed).
 */
function checkSchemaTask({against, report, version}) {
  return async function checkSchema() {
    const previous = await againstSet(against, version);
    const results = await compareSets(previous, await generatedSet());
    // a directory's path means nothing to readers of the report
    const text = formatReport(results, previous.isRelease ? previous.label : null);
    if (report) fs.writeFileSync(report, text ?? '');
    if (text != null) {
      console.log(text);
      throw new Error(`JSON schemas are not compatible with ${previous.label}`);
    }
    console.log(`JSON schemas are compatible with ${previous.label}`);
  };
}

/**
 * Task that replaces each schema in `outDir` with its counterpart from the previous release, if they are compatible -
 * so that its `$id` (which names the release it comes from) changes only when the contract does.
 */
function reuseSchemasTask({outDir, version}) {
  return async function reuseSchemas() {
    let previous;
    try {
      previous = await againstSet(null, version);
    } catch (e) {
      // publishing a new `$id` for an unchanged contract is harmless, but should not go unnoticed
      console.warn(`Could not load the previous release's JSON schemas; publishing new ones. ${e.message}`);
      return;
    }
    const results = await compareSets(previous, await generatedSet());
    const reused = Object.fromEntries(results.filter(({status}) => status === 'compatible').map(({file}) => [file, previous.files[file]]));
    Object.entries(reused).forEach(([file, text]) => fs.writeFileSync(path.join(outDir, file), text));
    results.filter(({status}) => status !== 'compatible').forEach(({file, status}) => {
      console.log(`JSON schema '${file}' is ${status} (compared with ${previous.label}); publishing a new version`);
      if (status === 'removed') return;
      const target = path.join(outDir, file);
      fs.writeFileSync(target, JSON.stringify(pointToReused(JSON.parse(fs.readFileSync(target, 'utf8')), file, reused), null, 2) + '\n');
    });
  };
}

/**
 * A reused schema keeps the `$id` of the release it comes from, so relative references to it from a new schema
 * (which resolve to the current release) would not find it; point them to that `$id` instead.
 */
function pointToReused(schema, file, reused) {
  const base = schema.$id.slice(0, -file.length);
  const ids = Object.fromEntries(Object.entries(reused).map(([reusedFile, text]) => [new URL(reusedFile, base).toString(), JSON.parse(text).$id]));
  const visit = (node) => {
    if (Array.isArray(node)) return node.map(visit);
    if (node == null || typeof node !== 'object') return node;
    return Object.fromEntries(Object.entries(node).map(([key, value]) => {
      if (key === '$ref' && typeof value === 'string' && !value.startsWith('#')) {
        const url = new URL(value, schema.$id);
        const hash = url.hash;
        url.hash = '';
        if (Object.hasOwn(ids, url.toString())) return [key, ids[url.toString()] + hash];
      }
      return [key, visit(value)];
    }));
  };
  return visit(schema);
}

module.exports = {compareSets, makeSet, generatedSet, dirSet, publishedSet, previousRelease, formatReport, jsonDiff, checkSchemaTask, reuseSchemasTask};
